"use client";

import React from "react";
import { Navigation } from "@/components/Navigation";
import { PageBackground } from "@/components/PageBackground";
import { BackLink } from "@/components/BackLink";
import { ScrollReveal } from "@/components/ScrollReveal";

export default function CapabilitiesPage() {
    return (
        <div className="relative w-full min-h-screen text-white overflow-x-hidden">
            <PageBackground />
            <Navigation />
            <BackLink />

            {/* ─── Hero ─── */}
            <ScrollReveal className="relative z-10 pt-12 pb-20 px-8">
                <div className="max-w-5xl mx-auto text-center">
                    <h1 className="text-6xl md:text-8xl font-extrabold tracking-tighter text-gradient mb-6 drop-shadow-2xl">
                        Capabilities
                    </h1>
                    <p className="text-lg md:text-xl text-gray-400 max-w-2xl mx-auto tracking-wide font-medium">
                        Autonomous reliability — from signal ingestion to self-healing infrastructure
                    </p>
                </div>
            </ScrollReveal>

            {/* ═══════════════════════════════════════════════
                SECTION 1 — Wide Band Layout
                Telemetry ingestion and anomaly detection
            ═══════════════════════════════════════════════ */}
            <ScrollReveal delay={0.1} className="relative z-10 px-8 mb-32">
                <div
                    className="w-full max-w-7xl mx-auto rounded-[2rem] overflow-hidden"
                    style={{
                        background: "linear-gradient(135deg, rgba(74, 14, 96, 0.08) 0%, rgba(15, 17, 23, 0.5) 50%, rgba(5, 5, 5, 0.3) 100%)",
                        backdropFilter: "blur(12px)",
                    }}
                >
                    {/* Top glow line */}
                    <div className="w-full h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/20 to-transparent" />

                    <div className="flex flex-col lg:flex-row min-h-[420px]">
                        {/* Left text block */}
                        <div className="flex-1 p-12 lg:p-16 flex flex-col justify-center">
                            <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#E0B0FF]/60 mb-6">01 — Observe</div>
                            <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-6 leading-[1.15]">
                                Telemetry Ingestion<br />
                                <span className="text-gray-500">&amp; Anomaly Detection</span>
                            </h2>
                            <p className="text-gray-400 leading-relaxed max-w-lg mb-8">
                                AEGIS absorbs millions of signals per second — traces, metrics, logs, and events — feeding
                                them through a multi-layered anomaly detection mesh. Temporal pattern recognition surfaces
                                deviations before they cascade into outages.
                            </p>
                            <div className="flex gap-12 text-sm font-mono">
                                <div>
                                    <div className="text-[#E0B0FF] text-2xl font-bold mb-1">1.2M</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Events / sec</div>
                                </div>
                                <div>
                                    <div className="text-[#E0B0FF] text-2xl font-bold mb-1">&lt;50ms</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Detection latency</div>
                                </div>
                                <div>
                                    <div className="text-[#E0B0FF] text-2xl font-bold mb-1">99.97%</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Precision</div>
                                </div>
                            </div>
                        </div>

                        {/* Right abstract visual surface */}
                        <div className="flex-1 relative min-h-[300px] lg:min-h-0 overflow-hidden">
                            {/* Layered depth surfaces instead of icons/images */}
                            <div className="absolute inset-0" style={{
                                background: `
                                    radial-gradient(ellipse 60% 40% at 60% 50%, rgba(224, 176, 255, 0.06) 0%, transparent 70%),
                                    radial-gradient(ellipse 30% 50% at 80% 30%, rgba(74, 14, 96, 0.12) 0%, transparent 60%)
                                `
                            }} />

                            {/* Floating depth layers */}
                            <div className="absolute top-16 right-12 w-[180px] h-[120px] rounded-2xl"
                                style={{
                                    background: "linear-gradient(145deg, rgba(224,176,255,0.04) 0%, rgba(74,14,96,0.08) 100%)",
                                    border: "1px solid rgba(224,176,255,0.06)",
                                    boxShadow: "0 20px 60px rgba(74,14,96,0.1)",
                                }}
                            />
                            <div className="absolute bottom-20 right-24 w-[140px] h-[200px] rounded-2xl"
                                style={{
                                    background: "linear-gradient(160deg, rgba(224,176,255,0.03) 0%, rgba(15,17,23,0.4) 100%)",
                                    border: "1px solid rgba(255,255,255,0.04)",
                                    boxShadow: "0 30px 80px rgba(0,0,0,0.3)",
                                }}
                            />
                            <div className="absolute top-32 right-40 w-[100px] h-[100px] rounded-full"
                                style={{
                                    background: "radial-gradient(circle, rgba(224,176,255,0.08) 0%, transparent 70%)",
                                    filter: "blur(20px)",
                                }}
                            />

                            {/* Animated scan line */}
                            <div className="absolute inset-x-0 h-px opacity-20"
                                style={{
                                    background: "linear-gradient(90deg, transparent 0%, #E0B0FF 50%, transparent 100%)",
                                    top: "60%",
                                }}
                            />
                        </div>
                    </div>

                    {/* Bottom glow line */}
                    <div className="w-full h-px bg-gradient-to-r from-transparent via-white/5 to-transparent" />
                </div>
            </ScrollReveal>

            {/* ═══════════════════════════════════════════════
                SECTION 2 — Bento Cluster Layout
                Root cause reasoning and correlation
            ═══════════════════════════════════════════════ */}
            <ScrollReveal delay={0.1} className="relative z-10 px-8 mb-32">
                <div className="max-w-7xl mx-auto">
                    <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#E0B0FF]/60 mb-6 px-2">02 — Reason</div>

                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 auto-rows-auto">
                        {/* Large primary block — spans 7 columns */}
                        <div
                            className="lg:col-span-7 rounded-[2rem] p-12 lg:p-14 flex flex-col justify-between min-h-[400px] relative overflow-hidden"
                            style={{
                                background: "linear-gradient(160deg, rgba(74,14,96,0.1) 0%, rgba(15,17,23,0.6) 60%, rgba(5,5,5,0.4) 100%)",
                                backdropFilter: "blur(16px)",
                            }}
                        >
                            {/* Inner glow */}
                            <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/15 to-transparent" />
                            <div className="absolute -top-20 -left-20 w-60 h-60 rounded-full"
                                style={{ background: "radial-gradient(circle, rgba(224,176,255,0.04) 0%, transparent 70%)" }}
                            />

                            <div className="relative z-10">
                                <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-5 leading-[1.15]">
                                    Root Cause Reasoning<br />
                                    <span className="text-gray-500">&amp; Signal Correlation</span>
                                </h2>
                                <p className="text-gray-400 leading-relaxed max-w-md">
                                    LLM-powered reasoning engine cross-references telemetry streams, deployment manifests,
                                    and historical incident data to isolate root causes with surgical accuracy. Multi-hop
                                    causal inference chains replace manual runbook triage.
                                </p>
                            </div>

                            <div className="relative z-10 flex gap-10 mt-8 text-sm font-mono">
                                <div>
                                    <div className="text-[#E0B0FF] text-xl font-bold mb-1">94%</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Accuracy</div>
                                </div>
                                <div>
                                    <div className="text-[#E0B0FF] text-xl font-bold mb-1">&lt;200ms</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Inference</div>
                                </div>
                            </div>
                        </div>

                        {/* Two smaller supporting blocks — stacked in 5 columns */}
                        <div className="lg:col-span-5 flex flex-col gap-6">
                            {/* Supporting block 1 — taller */}
                            <div
                                className="rounded-[2rem] p-10 flex-[1.3] flex flex-col justify-center relative overflow-hidden"
                                style={{
                                    background: "linear-gradient(145deg, rgba(224,176,255,0.04) 0%, rgba(15,17,23,0.5) 100%)",
                                    backdropFilter: "blur(12px)",
                                }}
                            >
                                <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-white/5 to-transparent" />
                                <h3 className="text-xl font-bold text-white mb-3">Multi-Hop Causal Chains</h3>
                                <p className="text-gray-400 text-sm leading-relaxed">
                                    Traces correlation paths across distributed services, linking
                                    upstream triggers to downstream failures through temporal and
                                    topological analysis.
                                </p>
                            </div>

                            {/* Supporting block 2 — shorter */}
                            <div
                                className="rounded-[2rem] p-10 flex-[0.7] flex flex-col justify-center relative overflow-hidden"
                                style={{
                                    background: "linear-gradient(170deg, rgba(74,14,96,0.06) 0%, rgba(10,12,16,0.6) 100%)",
                                    backdropFilter: "blur(12px)",
                                }}
                            >
                                <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/10 to-transparent" />
                                <h3 className="text-xl font-bold text-white mb-3">Historical Context</h3>
                                <p className="text-gray-400 text-sm leading-relaxed">
                                    Every hypothesis is enriched with incident memory — past
                                    resolutions, outcome effectiveness, and failure mode patterns
                                    from your infrastructure history.
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </ScrollReveal>

            {/* ═══════════════════════════════════════════════
                SECTION 3 — Split Vertical Layout
                Autonomous remediation workflows
            ═══════════════════════════════════════════════ */}
            <ScrollReveal delay={0.1} className="relative z-10 px-8 mb-32">
                <div className="max-w-7xl mx-auto">
                    <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#E0B0FF]/60 mb-6 px-2">03 — Act</div>

                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                        {/* Left — text-heavy column (wider) */}
                        <div
                            className="lg:col-span-5 rounded-[2rem] p-12 flex flex-col justify-center min-h-[480px] relative overflow-hidden"
                            style={{
                                background: "linear-gradient(150deg, rgba(74,14,96,0.07) 0%, rgba(10,12,16,0.5) 100%)",
                                backdropFilter: "blur(12px)",
                            }}
                        >
                            <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/12 to-transparent" />

                            <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-5 leading-[1.15]">
                                Autonomous<br />
                                <span className="text-gray-500">Remediation</span>
                            </h2>
                            <p className="text-gray-400 leading-relaxed mb-8">
                                AEGIS doesn't just diagnose — it acts. Approved remediation
                                workflows execute infrastructure-level operations: process termination,
                                resource scaling, deployment rollbacks, and configuration hot-patches.
                            </p>
                            <p className="text-gray-400 leading-relaxed mb-10">
                                Every action is gated by configurable approval policies.
                                Low-risk operations execute autonomously. High-risk actions surface
                                for human validation with full context and confidence scoring.
                            </p>

                            <div className="flex flex-col gap-4">
                                {["Process Lifecycle Management", "Horizontal & Vertical Scaling", "Deployment Rollback Chains", "Config Hot-Patch Execution"].map((item, i) => (
                                    <div key={i} className="flex items-center gap-3 group">
                                        <div className="w-1.5 h-1.5 rounded-full bg-[#E0B0FF]/40 group-hover:bg-[#E0B0FF] transition-colors" />
                                        <span className="text-sm text-gray-300 tracking-wide">{item}</span>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Right — visual-heavy column (wider) */}
                        <div
                            className="lg:col-span-7 rounded-[2rem] relative min-h-[480px] overflow-hidden"
                            style={{
                                background: "linear-gradient(165deg, rgba(224,176,255,0.03) 0%, rgba(5,5,5,0.4) 40%, rgba(15,17,23,0.5) 100%)",
                                backdropFilter: "blur(8px)",
                            }}
                        >
                            <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-white/5 to-transparent" />

                            {/* Abstract depth composition */}
                            <div className="absolute inset-0" style={{
                                background: `
                                    radial-gradient(ellipse 50% 60% at 40% 40%, rgba(74,14,96,0.1) 0%, transparent 70%),
                                    radial-gradient(ellipse 30% 30% at 70% 70%, rgba(224,176,255,0.04) 0%, transparent 60%)
                                `
                            }} />

                            {/* Workflow step layers — abstract surfaces */}
                            <div className="absolute top-12 left-10 right-10 flex flex-col gap-3">
                                {[
                                    { label: "DETECT", w: "85%" },
                                    { label: "ANALYZE", w: "70%" },
                                    { label: "PROPOSE", w: "55%" },
                                    { label: "EXECUTE", w: "40%" },
                                ].map((step, i) => (
                                    <div key={i} className="flex items-center gap-4">
                                        <div
                                            className="h-12 rounded-xl flex items-center px-5"
                                            style={{
                                                width: step.w,
                                                background: `linear-gradient(90deg, rgba(224,176,255,${0.03 + i * 0.015}) 0%, rgba(74,14,96,${0.04 + i * 0.02}) 100%)`,
                                                border: `1px solid rgba(224,176,255,${0.04 + i * 0.02})`,
                                            }}
                                        >
                                            <span className="text-xs font-mono uppercase tracking-[0.25em] text-gray-500">{step.label}</span>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            {/* Connecting flow line */}
                            <div className="absolute left-16 top-16 bottom-20 w-px"
                                style={{
                                    background: "linear-gradient(180deg, rgba(224,176,255,0.15) 0%, rgba(224,176,255,0.02) 100%)",
                                }}
                            />

                            {/* Bottom metrics */}
                            <div className="absolute bottom-10 left-10 right-10 flex gap-10 text-sm font-mono">
                                <div>
                                    <div className="text-[#E0B0FF] text-xl font-bold mb-1">0</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Human Interventions</div>
                                </div>
                                <div>
                                    <div className="text-[#E0B0FF] text-xl font-bold mb-1">&lt;4s</div>
                                    <div className="text-gray-500 uppercase tracking-wider text-xs">Mean Time to Remediate</div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </ScrollReveal>

            {/* Bottom spacer */}
            <div className="relative z-10 h-32" />
        </div>
    );
}
